 "content": "from collections import Counter


def transform(grid):
    """Connect aligned non-dominant tile-core colors through zero-valued gaps."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    if len(counts) < 2:
        return out
    frame = counts.most_common(1)[0][0]
    inner_counts = Counter(v for row in grid for v in row if v not in (0, frame))
    if not inner_counts:
        return out
    dominant = inner_counts.most_common(1)[0][0]
    signals = set(inner_counts) - {dominant}

    # Rows and columns are independent alignments. Preserve every nonzero cell;
    # only zero gaps bracketed by occurrences of the same signal are filled.
    for r in range(h):
        for color in signals:
            positions = [c for c, value in enumerate(grid[r]) if value == color]
            if len(positions) >= 2:
                for c in range(positions[0], positions[-1] + 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
    for c in range(w):
        for color in signals:
            positions = [r for r in range(h) if grid[r][c] == color]
            if len(positions) >= 2:
                for r in range(positions[0], positions[-1] + 1):
                    if grid[r][c] == 0 and out[r][c] == 0:
                        out[r][c] = color
    return out
